-- Migration 041: Nursery leachate log (Nursery > Logs > Leachate), with the 2026 history from the Field Leachate sheet of
-- WebbNursery_2026.xlsx (May 5 - Jun 22, Webb hoops 1-18, Zion hoops 1-6, greenhouse). Generated by tools/import_leachate.py.
-- One row = one hoop on one day: what came out (leachate volume, EC, pH) and what went in (front and back emitters).
-- Run after 031. Safe to re-run (the imported history is replaced, anything entered in the app is kept).
set client_min_messages = warning;

create table if not exists nursery_leachate (
  id            bigserial primary key,
  site          text not null default '1PN' references nursery_sites(code) on update cascade,
  room_id       int references nursery_rooms(id) on delete set null,
  bed           text,
  taken_on      date not null default current_date,
  minutes       numeric,            -- total run time
  leach_vol     numeric,            -- leachate volume collected (as written on the sheet)
  leach_ec      numeric,
  leach_ph      numeric,
  front_ml      numeric, front_ec numeric, front_ph numeric,   -- input, front of the hoop
  back_ml       numeric, back_ec  numeric, back_ph  numeric,   -- input, back of the hoop
  water_ml_plant numeric,           -- water applied per plant
  expect_pct    numeric,            -- input expectation %
  leach_pct     numeric,            -- plant leachate %
  notes         text,
  source        text not null default 'app',
  created_by    text default current_email(),
  created_at    timestamptz not null default now()
);
create index if not exists nursery_leachate_day on nursery_leachate (taken_on desc);
alter table nursery_leachate enable row level security;
drop policy if exists n_read on nursery_leachate;
drop policy if exists n_add on nursery_leachate;
drop policy if exists n_edit on nursery_leachate;
drop policy if exists n_delete on nursery_leachate;
create policy n_read on nursery_leachate for select to authenticated using (has_module('nursery') or is_admin());
create policy n_add on nursery_leachate for insert to authenticated with check (can_edit('nursery') and not impersonating());
create policy n_edit on nursery_leachate for update to authenticated using (can_edit('nursery')) with check (can_edit('nursery') and not impersonating());
create policy n_delete on nursery_leachate for delete to authenticated using (can_edit('nursery') and not impersonating());
grant select, insert, update, delete on nursery_leachate to authenticated;
grant usage on sequence nursery_leachate_id_seq to authenticated;

delete from nursery_leachate where source = 'import Webb2026';
insert into nursery_leachate (room_id, taken_on, minutes, leach_vol, leach_ec, leach_ph, front_ml, front_ec, front_ph, back_ml, back_ec, back_ph,
